def knapsack(W, val, wt):
    def f(i, c):               # best from the first i items, capacity c
        if i == 0:
            return 0
        best = f(i - 1, c)
        if wt[i - 1] <= c:
            best = max(best, val[i - 1] + f(i - 1, c - wt[i - 1]))
        return best
    return f(len(val), W)

def knapsack(W, val, wt):
    @cache
    def f(i, c):
        if i == 0:
            return 0
        best = f(i - 1, c)
        if wt[i - 1] <= c:
            best = max(best, val[i - 1] + f(i - 1, c - wt[i - 1]))
        return best
    return f(len(val), W)

def knapsack(W, val, wt):
    n = len(val)
    dp = [[0] * (W + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        w, v = wt[i - 1], val[i - 1]
        for c in range(W + 1):
            dp[i][c] = dp[i - 1][c]
            if w <= c:
                dp[i][c] = max(dp[i][c], v + dp[i - 1][c - w])
    return dp[n][W]

def knapsack(W, val, wt):
    prev = [0] * (W + 1)       # row i-1
    for w, v in zip(wt, val):
        cur = prev[:]          # leaving the item is the default
        for c in range(w, W + 1):
            cur[c] = max(prev[c], v + prev[c - w])
        prev = cur
    return prev[W]

def knapsack(W, val, wt):
    dp = [0] * (W + 1)
    for w, v in zip(wt, val):
        for c in range(W, w - 1, -1):     # downwards: each item once
            dp[c] = max(dp[c], v + dp[c - w])
    return dp[W]
